head.script:
scwin.onpageload = function () {
};

scwin.setDataAndRender = function () {
    try {
        scwin.loginCustomInfo = aliasDataMap1.getObj();

        scwin.addColor("overlayColor", colorGroup, scwin.loginCustomInfo.get("overlayColor"));
        scwin.addSlider(scwin.loginCustomInfo.get("overlayOpacity"));
        scwin.addUpload();

    } catch (e) {
        console.error("데이터를 이용한 UI 렌더링 중 오류가 발생했습니다.", e);
    }
};

scwin.addUpload = function () {
    // 1. input 요소 생성
    var fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';      // 허용할 파일 타입 (옵션)
    // fileInput.multiple = true;         // 다중 선택 허용 (옵션)
    fileInput.style.display = 'none'; // input 자체는 숨기기 (label 클릭으로 대체)
    bgImgGroup.appendChild(fileInput);

    fileNameDisplay.bind("onclick", function () {
        fileInput.click();
    });

    // 2. change 이벤트 핸들러 등록
    fileInput.addEventListener('change', function (event) {
        var file = event.target.files[0];
        if (!file) {
            return;
        }

        fileNameDisplay.setValue(file.name);

        var reader = new FileReader();
        reader.onload = function (e) {
            scwin.loginCustomInfo.set("backgroundImage", e.target.result);
        };

        reader.readAsDataURL(file);

        // 선택 직후 서버로 전송하려면 FormData 사용
        // var formData = new FormData();
        // Array.from(files).forEach(f => formData.append('files', f));
        // fetch('/upload/api', { method: 'POST', body: formData })
        //   .then(res => res.json())
        //   .then(json => console.log('업로드 결과:', json))
        //   .catch(err => console.error(err));
    });
}

scwin.addSlider = function (opacity) {
    // input 엘리먼트 생성
    var slider = document.createElement("input");
    slider.type = "range";
    slider.id = "customSlider";
    slider.min = "0";
    slider.max = "100";
    slider.value = opacity;
    slider.step = "1";
    slider.style.width = "100%";

    // 이벤트 바인딩
    slider.addEventListener("input", function () {
        scwin.loginCustomInfo.set("overlayOpacity", slider.value);
        opacity_text.setValue("오버레이 투명도 : " + slider.value + "%");
    });

    // DOM에 추가
    sliderGroup.appendChild(slider);
    opacity_text.setValue("오버레이 투명도 : " + slider.value + "%");
}

scwin.addColor = function (id, colorGroup, color1) {

    // input 엘리먼트 생성
    var color = document.createElement("input");
    color.type = "color";
    color.style.width = "100%";
    color.style.height = "35px";
    color.id = id;
    color.value = color1

    // 이벤트 바인딩
    color.addEventListener("input", function () {
        scwin.loginCustomInfo.set("overlayColor", color.value);
    });

    // DOM에 추가
    colorGroup.appendChild(color);
}
